import type { Metadata } from "next";
import { siteConfig } from "@/data/site-config";

/** Default share image, generated by `npm run og` (scripts/generate-og.mjs). */
export const defaultOgImage = {
  url: "/og/spacecraft-interiors.jpg",
  width: 1200,
  height: 630,
  alt: "SpaceCraft Interiors — office, retail and commercial interior design in Kolkata",
};

/** Absolute URL for a site path, e.g. absoluteUrl("/about/"). */
export const absoluteUrl = (path = "/") => new URL(path, siteConfig.url).toString();

/**
 * Complete per-page metadata. Next.js merges metadata shallowly, so `openGraph` and `twitter`
 * are always built in full here rather than partly inherited from the root layout.
 */
export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
  noindex = false,
}: {
  title: string;
  description: string;
  /** Site path with trailing slash, e.g. "/about/" */
  path: string;
  /** Use `title` as-is instead of appending " | SpaceCraft Interiors" */
  absoluteTitle?: boolean;
  noindex?: boolean;
}): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${siteConfig.name}`;
  return {
    title: { absolute: fullTitle },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: siteConfig.name,
      locale: siteConfig.locale,
      url: path,
      title: fullTitle,
      description,
      images: [defaultOgImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [defaultOgImage.url],
    },
    robots: noindex ? { index: false, follow: true } : undefined,
  };
}
